// 引入 Node.js 原生加密模块（n8n 默认允许引用）
const crypto = require('crypto');

// ⚠️ 在这里填入你的钉钉 Token 和 SEC 密钥
const accessToken = 'c8f75452059bd89fa1010da170936e7360168e22ea38eec5efba57356ffbfcfe'; 
const secret = 'SECaabc74a6447a606341409e631803d3030e62d737755237cba4f56f229f87a191';

// 遍历流经此节点的所有数据项
for (const item of $input.all()) {
  // 1. 获取当前毫秒时间戳
  const timestamp = new Date().getTime();

  // 2. 拼接待签名字符串
  const stringToSign = timestamp + '\n' + secret;

  // 3. 计算 HMAC-SHA256 加密并转为 Base64
  const hash = crypto.createHmac('sha256', secret).update(stringToSign).digest('base64');

  // 4. 对生成的 Base64 字符串进行 URL 编码
  const sign = encodeURIComponent(hash);

  // 5. 将完整的 URL 附加到当前数据流中，命名为 webhook_url
  item.json.webhook_url = `https://oapi.dingtalk.com/robot/send?access_token=${accessToken}&timestamp=${timestamp}&sign=${sign}`;
}

// 返回处理后的数据
return $input.all();

